// Demonstrates: regen-idempotent, workflow.dot.
package generate

import (
	"bytes"
	"crypto/sha256"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"

	"github.com/go-playground/errors/v5"
)

// TestGeneratedCodeIsCommitted re-runs the full generation pipeline and fails if any
// generated file differs from the state on disk. The zz_gen files (Go, TypeScript, DOT,
// JSON) are the golden output of the resource generators: any drift here is a generator
// behavior change that must be either intentional (commit the new output) or a
// regression. The comparison is between the files as they were when this package's
// tests started (TestMain) and as they are after the run, so it holds whether the tree
// is committed or still untracked, and it counts what another test of the package
// regenerated in place before this one ran.
//
// Requires the Spanner emulator (podman/docker), like the rest of this module's tests.
func TestGeneratedCodeIsCommitted(t *testing.T) {
	if testing.Short() {
		t.Skip("generation requires the Spanner emulator")
	}

	before := generatedAtStart
	if before == nil {
		t.Fatal("the generated files were not hashed when the package's tests started (TestMain)")
	}
	root, err := moduleRoot()
	if err != nil {
		t.Fatal(err)
	}

	generate := exec.CommandContext(t.Context(), "go", "generate", "./...")
	generate.Dir = root
	if out, err := generate.CombinedOutput(); err != nil {
		t.Fatalf("go generate ./...: %v\n%s", err, out)
	}

	after, err := hashGeneratedFiles(root)
	if err != nil {
		t.Fatal(err)
	}

	var drift []string
	for path, sum := range after {
		if before[path] != sum {
			drift = append(drift, path)
		}
	}
	for path := range before {
		if _, ok := after[path]; !ok {
			drift = append(drift, path+" (removed)")
		}
	}
	if len(drift) > 0 {
		t.Errorf("generator output differs from the state on disk; if the change is intentional, commit the regenerated files:\n%s", strings.Join(drift, "\n"))
	}
}

// generatedHeader opens every Go file the generator writes, whatever the file is named.
const generatedHeader = "// Code generated by resourcegeneration. DO NOT EDIT."

// moduleRoot is the root of this module, two directories above this file.
func moduleRoot() (string, error) {
	_, thisFile, _, ok := runtime.Caller(0)
	if !ok {
		return "", errors.New("runtime.Caller failed")
	}

	return filepath.Join(filepath.Dir(thisFile), "..", ".."), nil
}

// hashGeneratedFiles maps every generated file under the module to its content hash:
// every zz_gen file, and every Go file that opens with the generator's header, which is
// how the files of a tree the generator owns whole are told (the generated management of
// the auths, GenerateIdentity: its sources carry plain names). No directory is named, so
// the test holds wherever a program writes such a tree. The Angular workspaces'
// node_modules are excluded.
func hashGeneratedFiles(root string) (map[string][32]byte, error) {
	// The files that may be generated: the zz_gen files, and every Go file, which is
	// read below to see whether it opens with the header.
	named := map[string]bool{}
	var paths []string
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == "node_modules" || d.Name() == ".angular" || d.Name() == "dist" {
				return filepath.SkipDir
			}

			return nil
		}
		if strings.Contains(d.Name(), "zz_gen") {
			named[path] = true
		}
		if named[path] || strings.HasSuffix(d.Name(), ".go") {
			paths = append(paths, path)
		}

		return nil
	})
	if err != nil {
		return nil, errors.Wrap(err, "filepath.WalkDir()")
	}

	sums := make(map[string][32]byte)
	for _, path := range paths {
		raw, err := os.ReadFile(path)
		if err != nil {
			return nil, errors.Wrap(err, "os.ReadFile()")
		}
		if !named[path] && !bytes.HasPrefix(raw, []byte(generatedHeader)) {
			continue
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return nil, errors.Wrap(err, "filepath.Rel()")
		}
		sums[rel] = sha256.Sum256(raw)
	}

	return sums, nil
}
